import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    PointLight,
    Color,
  } = ctx.THREE;

  const root = new Group();
  root.name = 'home-quote-panel';
  root.userData.handlers = {};

  const timelines = [];
  const primitiveResults = [];
  const ownedResources = [];
  let disposed = false;

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const panel = new Group();
  panel.name = 'quote-panel-depth-stack';
  root.add(panel);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.46,
    depthWrite: false,
  });
  const shadow = new Mesh(
    new CircleGeometry(1.85, 64),
    shadowMaterial,
  );
  shadow.name = 'contact-shadow';
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(1.35, 0.42, 1);
  shadow.position.set(0.06, -1.02, -0.2);
  root.add(shadow);
  ownedResources.push(shadow.geometry, shadow.material);

  const backingMaterial = new MeshStandardNodeMaterial({
    color: surface,
    roughness: 0.72,
    metalness: 0.42,
  });
  const backing = new Mesh(
    new BoxGeometry(2.94, 1.89, 0.16),
    backingMaterial,
  );
  backing.name = 'machined-metal-backplate';
  backing.position.z = -0.13;
  panel.add(backing);
  ownedResources.push(backing.geometry, backing.material);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: paper,
    transparent: false,
  });
  const imageGeometry = new PlaneGeometry(2.8, 1.75, 64, 64);
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'parallax-image-plane';
  imagePlane.position.z = 0.01;
  panel.add(imagePlane);
  ownedResources.push(imageGeometry, imageMaterial);

  const frameMaterial = new MeshStandardNodeMaterial({
    color: ink,
    roughness: 0.58,
    metalness: 0.52,
  });
  const topFrame = new Mesh(new BoxGeometry(3.08, 0.075, 0.12), frameMaterial);
  const bottomFrame = new Mesh(new BoxGeometry(3.08, 0.075, 0.12), frameMaterial);
  const leftFrame = new Mesh(new BoxGeometry(0.075, 1.9, 0.12), frameMaterial);
  const rightFrame = new Mesh(new BoxGeometry(0.075, 1.9, 0.12), frameMaterial);

  topFrame.position.set(0, 0.94, 0.08);
  bottomFrame.position.set(0, -0.94, 0.08);
  leftFrame.position.set(-1.5, 0, 0.08);
  rightFrame.position.set(1.5, 0, 0.08);

  panel.add(topFrame, bottomFrame, leftFrame, rightFrame);
  ownedResources.push(
    topFrame.geometry,
    bottomFrame.geometry,
    leftFrame.geometry,
    rightFrame.geometry,
    frameMaterial,
  );

  const accentMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: new Color(accent),
    emissiveIntensity: 1.15,
    roughness: 0.52,
    metalness: 0.3,
  });
  const accentRail = new Mesh(
    new BoxGeometry(0.045, 1.42, 0.045),
    accentMaterial,
  );
  accentRail.name = 'signal-red-rim';
  accentRail.position.set(-1.39, -0.04, 0.17);
  panel.add(accentRail);
  ownedResources.push(accentRail.geometry, accentRail.material);

  const keyLight = new PointLight(paper, 0.72, 5.5, 2);
  keyLight.position.set(-2.1, 2.2, 2.4);
  panel.add(keyLight);

  const rimLight = new PointLight(accent, 0.78, 4.5, 2);
  rimLight.position.set(1.8, -0.3, 1.4);
  panel.add(rimLight);

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((imageTexture) => {
      if (disposed) return;
      imageTexture.colorSpace = 'srgb';
      imageMaterial.colorNode = texture(imageTexture);
      imageMaterial.needsUpdate = true;
    });
  }

  if (depthMapUrl) {
    ctx.textureLoader.loadTexture(depthMapUrl).then((depthTexture) => {
      if (disposed) return;
      const depthNode = texture(depthTexture);
      imageMaterial.positionNode = positionLocal.add(
        normalLocal.mul(depthNode.r.sub(0.5).mul(0.16)),
      );
      imageMaterial.needsUpdate = true;
    });
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' },
  ).to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.48,
    ease: 'power4.out',
  }, '>-0.02');
  entrance.fromTo(
    root.position,
    { z: -0.22 },
    { z: 0, duration: 0.7, ease: 'power3.out' },
    0,
  );
  entrance.play();
  timelines.push(entrance);

  const hoverUp = gsap.timeline({ paused: true });
  hoverUp.to(root.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out',
  });
  hoverUp.reverse();
  timelines.push(hoverUp);

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;
    hoverUp.reversed(!active);
  };

  root.userData.handlers.click = () => {
    if (disposed) return;
    const press = gsap.timeline();
    press.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out',
    }).to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.42,
      ease: 'back.out',
    });
    timelines.push(press);
    ctx.emit('hub-home.select', { node: root.name });
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    const apply = ctx.primitives?.[primitive.name];
    if (typeof apply === 'function') {
      const result = apply(root, primitive.params);
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const resource of ownedResources) {
      resource?.dispose?.();
    }

    root.clear();
  };

  return root;
}
